// Where every doc lives on the site. scripts/sync.mjs writes the pages, astro.config.mjs builds the sidebar from
// the same list, and the sync fails if a file in ../docs/ is not placed here.

/** The public address of the site. Override with SITE_URL at build time (for example a custom domain). */
export const SITE = process.env.SITE_URL || 'https://kuukura-main-landing.workers.dev';

export const REPO = 'https://github.com/victorlunam/kuukura';

